        if s.shape_type==6: walk(s.shapes,ind+2)
        if s.has_table if hasattr(s,'has_table') else False: print(' '*ind+'  TABLE', len(s.table.rows), len(s.table.columns))
for i in ids:
    print('=== slide',i, p.slides[i-1].slide_layout.name); walk(p.slides[i-1].shapes,1)
EOF
